fs.mkdirSync(OUT, { recursive: true });
const manifest = pages.map(({ content, ...m }) => ({ ...m, file: `${m.slug}.html` }));
for (const pg of pages) fs.writeFileSync(path.join(OUT, `${pg.slug}.html`), pg.content + '\n');
